 {modal==='share'&&shareLink&&room&&canViewRoom(room,who?.id)&&<><p id="share-help">Clipboard access is unavailable. Select the link, then copy it using your keyboard or your device's copy menu.</p><label>{shareLink.kind==='results'?'Results link':shareLink.kind==='code'?'Room code':'Invitation link'}<input readOnly value={shareLink.url} aria-describedby="share-help" onFocus={e=>e.currentTarget.select()} /></label><button type="button" className="button secondary" onClick={e=>{const input=e.currentTarget.parentElement?.querySelector('input');input?.focus();input?.select()}}>Select link</button><Button onClick={()=>setModal('')}>Done</Button><p className="fine-print">{shareLink.kind==='results'?'Only existing room members with access can open these results.':shareLink.kind==='code'?'Anyone with this code can join while the room is waiting and has space.':'Keep this invitation within your group. The host can renew it to replace this link.'}</p></>}
 {modal==='login'&&(clerkKey?<><p>Sign in to keep your rooms and squads connected to your account.</p><SignInButton mode="modal"><button className="button">Sign in</button></SignInButton><SignUpButton mode="modal"><button className="button secondary">Create account</button></SignUpButton></>:<><p>{localAuth?'Local development profile. This is a test identity on this device, not a production account.':'Account sign-in requires Clerk configuration. You can still explore the product preview.'}</p>{localAuth&&<form onSubmit={e=>{e.preventDefault();run(async()=>{const d=await api('/dev/session',{name});setToken(d.token);setUser(d.user);localStorage.setItem('aa-token',d.token);localStorage.setItem('aa-user',JSON.stringify(d.user));setModal(pendingModal.current||(code?'join':''));pendingModal.current='';setNotice('Local profile created. Welcome to the arena.');})}}><label>Display name<input autoFocus required minLength={2} maxLength={30} value={name} onChange={e=>setName(e.target.value)} placeholder="What should we call you?"/></label><button className="button" disabled={busy}>Continue locally <ArrowRight size={18}/></button></form>}</>)}
 {modal==='create'&&<form onSubmit={e=>{e.preventDefault();if(!review){setReview(true);return}run(async()=>{const d=await api('/rooms',settings);activateRoom(d);setInvite(d.inviteToken);sessionStorage.setItem('invite-'+d.room.code,d.inviteToken);setModal('');setScreen('room');history.replaceState(null,'',`?room=${d.room.code}`);setTab('auction');})}}>{review?<><div className="rules"><p>Mode <b>{settings.mode?auctionModeLabels[settings.mode]:'Custom'}</b></p><p>Room <b>{settings.name}</b></p><p>Private teams <b>{settings.teamCount}</b></p><p>Starting purse <b>{money(settings.budget)}</b></p><p>Squad <b>{settings.minSquad===settings.maxSquad?`${settings.minSquad} players`:`${settings.minSquad}–${settings.maxSquad} players`}</b></p><p>Nationality <b>{settings.mode?`at least ${auctionModeRules[settings.mode].minIndian} Indian · max ${settings.maxOverseas} overseas`:`max ${settings.maxOverseas} overseas`}</b></p><p>Timer <b>{settings.timerSeconds}s</b></p><p>Late extension <b>{settings.lateExtension?'Enabled':'Off'}</b></p></div><button type="button" className="text-button" onClick={()=>setReview(false)}>← Edit settings</button></>:<><CreateAuctionFields settings={settings} setSettings={setSettings}/></>}<p className="fine-print">Private room · Mode rules are fixed at creation · Seeded catalog player pool · Simulation rules.<br/>1 crore = 100 lakhs. No real money is involved.</p><button className="button" disabled={busy}>{review?'Create private auction':'Review settings'} <ArrowRight size={18}/></button></form>}
